      : 'No approval offered: ' + uniq(blocks).join('; '),
    summary: String(ai.owner_note || '').slice(0, 600),
    model: ai.no_model_call ? null : cfg.model,
    usage: ai.usage || {},
  },
}];

// Over the daily ceiling no email goes to the owner, so no approval can be offered either. The message and
// its status are still saved.
const gate = $('Decision Gate').first().json;
const n = $input.first().json || {};
const allowed = n.allowed === true;
const out = { ...gate, notify_allowed: allowed, first_held: n.first_held === true, notify_cap: n.cap || null };
if (!allowed) {
  out.approvable = false;
  out.blocks = gate.blocks.concat(['the daily limit of ' + (n.cap || 'the configured number of') + ' inbox emails was reached, so this message is held without an email']);
