return [{
  json: {
    approval_offered: offered && !!actionUrl,
    draft_id: saved.draft_id || null,
    sha256: saved.sha256 || null,
    idempotency_key: 'qylat-inbox-owner-' + String(saved.draft_id || $('Claim Message').first().json.message_id),
