// Read Decision (n8n Code node, run once for all items).
// Runs when the decision page was submitted or the wait ran out. Only an explicit choice counts.
// Anything else, including the wait ending with no answer, is treated as "expire": nothing is sent.
const owner = $('Build Owner Email').first().json;
const input = $input.first().json || {};
const choice = String(input.Decision || input.decision || '').trim().toLowerCase();
let decision = 'expire';
if (choice === 'send this reply') decision = 'approve';
else if (choice === 'do not send') decision = 'decline';
// The code is whatever was typed on the page. The database decides whether it is right.
const code = String(input['Approval code'] || input.approval_code || '').slice(0, 40);
return [{ json: { decision, draft_id: owner.draft_id, sha256: owner.sha256, code } }];

// Build Reply (n8n Code node, run once for all items).
// Builds the one email that can reach a customer. Every part of it comes from the database's answer
// to the send claim: the recipient, the subject, the threading ids and the exact approved text.
// Nothing is taken from the model or from earlier nodes.
const cfg = $('Config').first().json;
const claim = $('Claim Send').first().json || {};
const decision = $('Read Decision').first().json;

const subjectRaw = String(claim.subject || '').replace(/[\r\n]+/g, ' ').trim();
const subject = (/^re:/i.test(subjectRaw) ? subjectRaw : 'Re: ' + (subjectRaw || 'your message')).slice(0, 200);
const idOk = (v) => /^<[^<>\s]{3,300}>$/.test(String(v || ''));
const refs = (Array.isArray(claim.reference_ids) ? claim.reference_ids : []).filter(idOk).slice(-20);
const headers = {};
if (idOk(claim.in_reply_to)) headers['In-Reply-To'] = claim.in_reply_to;
if (refs.length) headers['References'] = refs.join(' ');

const to = String(claim.to_email || '').trim().toLowerCase();
const valid = claim.claimed === true && /^[^\s@<>,;]+@[^\s@<>,;]+\.[^\s@<>,;]+$/.test(to) && String(claim.reply_text || '').trim().length > 0;

return [{
  json: {
    valid,
    draft_id: decision.draft_id,
    idempotency_key: 'qylat-inbox-reply-' + decision.draft_id,
    payload: {
      from: cfg.reply_from,
      to: [to],
      reply_to: cfg.mailbox,
      subject,
      text: String(claim.reply_text || ''),
      headers,
    },
  },
}];

// Provider Outcome (n8n Code node, run once for each item). Shared by every step that hands an email
// to the sending provider. Only a 2xx answer carrying a message id counts as accepted. An answer that
// proves the provider refused the message is 'failed'. Anything else (timeout, network error, 5xx, 409)
